// =============================================================================
// gcd — 16-bit greatest-common-divisor block (Euclid, subtract-and-swap)
// CBflow open-source spec-to-GDS pilot (project opensky, sky130hd), phase P3.
// Spec: ../spec/gcd.spec.yaml; registers: ../spec/gcd_regs.rdl — the register
// block gcd_regs (+ gcd_regs_pkg) is generated by the RTL_SPEC flow
// (PeakRDL regblock, APB4).
// P3 = P2 (valid/ready compute, SRAM operand / result logs) + an APB register
// block: CTRL.irq_en / cnt_clr, STATUS.busy / done / irq, RESULT, OPCOUNT, and
// a level interrupt (irq = STATUS.irq & CTRL.irq_en).
// =============================================================================
module gcd
    import gcd_regs_pkg::*;
(
    input  wire        clk,
    input  wire        reset,
    // request: two 16-bit operands {a, b}
    input  wire        req_val,
    output wire        req_rdy,
    input  wire [31:0] req_msg,
    // response: gcd(a, b)
    output wire        resp_val,
    input  wire        resp_rdy,
    output wire [15:0] resp_msg,
    // APB4 register interface
    input  wire        s_apb_psel,
    input  wire        s_apb_penable,
    input  wire        s_apb_pwrite,
    input  wire [2:0]  s_apb_pprot,
    input  wire [3:0]  s_apb_paddr,
    input  wire [31:0] s_apb_pwdata,
    input  wire [3:0]  s_apb_pstrb,
    output wire        s_apb_pready,
    output wire [31:0] s_apb_prdata,
    output wire        s_apb_pslverr,
    // interrupt (result completed, CTRL.irq_en)
    output wire        irq
);
    localparam IDLE = 2'd0, CALC = 2'd1, DONE = 2'd2;

    reg [1:0]  state;
    reg [15:0] a, b;

    wire a_lt_b = (a < b);
    wire b_zero = (b == 16'd0);

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            a     <= 16'd0;
            b     <= 16'd0;
        end else begin
            case (state)
                IDLE: if (req_val) begin
                          a     <= req_msg[31:16];
                          b     <= req_msg[15:0];
                          state <= CALC;
                      end
                CALC: if (a_lt_b) begin
                          a <= b;                 // swap so a >= b
                          b <= a;
                      end else if (!b_zero) begin
                          a <= a - b;
                      end else begin
                          state <= DONE;
                      end
                DONE: if (resp_rdy) state <= IDLE;
                default: state <= IDLE;
            endcase
        end
    end

    assign req_rdy  = (state == IDLE);
    assign resp_val = (state == DONE);
    assign resp_msg = a;

    wire req_fire  = req_val  && req_rdy;
    wire resp_fire = resp_val && resp_rdy;

    // ── registers ───────────────────────────────────────────────────────
    gcd_regs__in_t  hwif_in;
    gcd_regs__out_t hwif_out;
    reg [15:0] last_result, op_count;

    always @(posedge clk) begin
        if (reset) begin
            last_result <= 16'd0;
            op_count    <= 16'd0;
        end else begin
            if (resp_fire) last_result <= a;
            if (hwif_out.CTRL.cnt_clr.value) op_count <= 16'd0;
            else if (resp_fire)              op_count <= op_count + 16'd1;
        end
    end

    assign hwif_in.STATUS.busy.next   = (state == CALC);
    assign hwif_in.STATUS.done.next   = (state == DONE);
    assign hwif_in.STATUS.irq.hwset   = resp_fire;
    assign hwif_in.RESULT.value.next  = last_result;
    assign hwif_in.OPCOUNT.count.next = op_count;
    assign irq = hwif_out.STATUS.irq.value & hwif_out.CTRL.irq_en.value;

    gcd_regs u_regs (
        .clk(clk), .rst(reset),
        .s_apb_psel(s_apb_psel), .s_apb_penable(s_apb_penable), .s_apb_pwrite(s_apb_pwrite),
        .s_apb_pprot(s_apb_pprot), .s_apb_paddr(s_apb_paddr), .s_apb_pwdata(s_apb_pwdata),
        .s_apb_pstrb(s_apb_pstrb), .s_apb_pready(s_apb_pready), .s_apb_prdata(s_apb_prdata),
        .s_apb_pslverr(s_apb_pslverr),
        .hwif_in(hwif_in), .hwif_out(hwif_out)
    );

    // ── SRAM logs ───────────────────────────────────────────────────────
    reg [7:0] req_ptr, resp_ptr;

    always @(posedge clk) begin
        if (reset) begin
            req_ptr  <= 8'd0;
            resp_ptr <= 8'd0;
        end else begin
            if (req_fire)  req_ptr  <= req_ptr  + 8'd1;
            if (resp_fire) resp_ptr <= resp_ptr + 8'd1;
        end
    end

    // operand log: {a, b} of each accepted request (port 0 write; port 1 idle)
    sky130_sram_1kbyte_1rw1r_32x256_8 u_sram_req (
        .clk0(clk), .csb0(~req_fire), .web0(1'b0), .wmask0(4'hF),
        .addr0(req_ptr), .din0(req_msg), .dout0(),
        .clk1(clk), .csb1(1'b1), .addr1(8'd0), .dout1()
    );

    // result log: gcd of each accepted response
    sky130_sram_1kbyte_1rw1r_32x256_8 u_sram_resp (
        .clk0(clk), .csb0(~resp_fire), .web0(1'b0), .wmask0(4'hF),
        .addr0(resp_ptr), .din0({16'd0, a}), .dout0(),
        .clk1(clk), .csb1(1'b1), .addr1(8'd0), .dout1()
    );
endmodule
